sys_script_include.script:
var CampusMatchNotificationService = Class.create();

CampusMatchNotificationService.prototype = {

    initialize: function() {

        this.TABLE =
            'x_snc_campusmatch_campusmatch_notification';

    },


    /* =====================================================
       CREATE NOTIFICATION FOR ONE USER
    ===================================================== */

    createForUser: function(
        userId,
        audience,
        title,
        message,
        targetUrl,
        notificationType,
        sourceTable,
        sourceSysId,
        dedupeKey,
        emailSubject
    ) {

        userId =
            (userId || '')
            .toString()
            .trim();


        if (!userId) {

            return '';

        }


        title =
            (title || '')
            .toString()
            .substring(
                0,
                160
            );


        message =
            (message || '')
            .toString()
            .substring(
                0,
                500
            );


        targetUrl =
            (targetUrl || '')
            .toString()
            .substring(
                0,
                500
            );


        dedupeKey =
            (dedupeKey || '')
            .toString()
            .substring(
                0,
                200
            );


        /* =================================================
           PREVENT DUPLICATE NOTIFICATIONS
        ================================================= */

        if (dedupeKey) {

            var existing =
                new GlideRecord(
                    this.TABLE
                );


            existing.addQuery(
                'recipient',
                userId
            );


            existing.addQuery(
                'dedupe_key',
                dedupeKey
            );


            existing.setLimit(
                1
            );


            existing.query();


            if (
                existing.next()
            ) {

                return existing
                    .getUniqueValue();

            }

        }


        /* =================================================
           CREATE NOTIFICATION
        ================================================= */

        var notification =
            new GlideRecord(
                this.TABLE
            );


        notification.initialize();


        notification.setValue(
            'recipient',
            userId
        );


        notification.setValue(
            'audience',
            audience || 'student'
        );


        notification.setValue(
            'title',
            title
        );


        notification.setValue(
            'message',
            message
        );


        notification.setValue(
            'target_url',
            targetUrl
        );


        notification.setValue(
            'notification_type',
            notificationType || 'claim'
        );


        notification.setValue(
            'source_table',
            sourceTable || ''
        );


        notification.setValue(
            'source_sys_id',
            sourceSysId || ''
        );


        notification.setValue(
            'dedupe_key',
            dedupeKey
        );


        /*
         * IMPORTANT:
         * Actual field name is "read"
         */

        notification.setValue(
            'read',
            false
        );


        notification.setValue(
            'email_subject',
            emailSubject || title
        );


        return notification.insert();

    },


    /* =====================================================
       CREATE NOTIFICATION FOR CAMPUSMATCH STAFF
    ===================================================== */

    notifyAdmins: function(
        title,
        message,
        targetUrl,
        notificationType,
        sourceTable,
        sourceSysId,
        dedupeKey,
        emailSubject
    ) {

        var roleUser =
            new GlideRecord(
                'sys_user_has_role'
            );


        /*
         * CampusMatch staff only
         */

        roleUser.addQuery(
            'role.name',
            'x_snc_campusmatch.staff'
        );


        roleUser.addQuery(
            'user.active',
            true
        );


        roleUser.query();


        var alreadyProcessed =
            {};


        while (
            roleUser.next()
        ) {

            var userId =
                roleUser.getValue(
                    'user'
                );


            if (
                !userId ||
                alreadyProcessed[
                    userId
                ]
            ) {

                continue;

            }


            alreadyProcessed[
                userId
            ] =
                true;


            this.createForUser(
                userId,
                'staff',
                title,
                message,
                targetUrl,
                notificationType,
                sourceTable,
                sourceSysId,
                dedupeKey,
                emailSubject
            );

        }

    },


    type:
        'CampusMatchNotificationService'

};
